+import type {WebSocket} from 'ws';
+import {sendSessionList} from './transport/ws/sender.js';
+import type {
+  IncomingMessage,
+  ListSessionsMessage,
+  OutgoingMessage,
+  SessionListMessage,
+  SessionListOptions,
+  SessionSummaryFrame,
+} from './index.js';
+
+// Wire frames carry ISO strings rather than Date instances, and a summary frame pages straight back in before.
+
+describe('the session list protocol types', () => {
+  it('exports ListSessionsMessage, SessionSummaryFrame, and SessionListMessage and sends a session_list frame', () => {
+    const summary: SessionSummaryFrame = {
+      sessionId: 's1',
+      createdAt: '2026-01-01T00:00:00.000Z',
+      updatedAt: '2026-01-01T00:02:00.000Z',
+      entryCount: 3,
+    };
+    const request: ListSessionsMessage = {
+      type: 'list_sessions',
+      limit: 20,
+      before: summary,
+    };
+    const incoming: IncomingMessage = request;
+    const listOptions: SessionListOptions = {limit: request.limit, before: request.before};
+    const sent: OutgoingMessage[] = [];
+    const ws = {send: (raw: string) => void sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
+
+    sendSessionList(ws, [summary]);
+    const expectedReply: SessionListMessage = {type: 'session_list', sessions: [summary]};
+
+    expect({incoming, listOptions, sent}).toEqual({
+      incoming: {type: 'list_sessions', limit: 20, before: summary},
+      listOptions: {limit: 20, before: summary},
+      sent: [expectedReply],
+    });
+  });
+});
